// LUMINARY 099 MASTER IGNITION ROUTINE
// BANK 36, SETLOC P40S
void BURN_BABY_BURN_MASTER_IGNITION(void) {
    // Initialize Pad-Loaded Erasable Registers
    *(double *)00364 = 15103.0; // Initial LM Mass (kg)
    *(double *)00540 = 0.10;    // LOWCRIT: 10% minimum throttle
    *(double *)00542 = 0.60;    // HIGHCRIT: 60% cavitation threshold
    *(double *)00370 = 0.0;     // Initial FP (Present Thrust)
    *(double *)00372 = 0.0;     // Initial FC (Guidance Command)
    *(double *)01400 = 1000.0;  // Initial Radar Altitude Gate (m)
}

// Scale demanded acceleration vector by current gross vehicle mass
double MASSMULT(double commanded_accel) {
    double vehicle_mass = *(double *)00364;
    return commanded_accel * vehicle_mass;
}

// MIT LUMINARY 099 - THROTTLE CONTROL (BANK 31)
// Enforces DPS engine non-linear piecewise bounds: [0.10, 0.60] or 1.00 (FLATOUT)
double THROTTLE_CONTROL_ROUTINES(double desired_accel) {
    double fc = MASSMULT(desired_accel);
    *(double *)00372 = fc; // Store FC
    double lowcrit = *(double *)00540;
    double highcrit = *(double *)00542;
    double effective_throttle = fc / 45000.0;
    if (effective_throttle <= lowcrit) {
        effective_throttle = lowcrit; // 10% minimum throttle stop
    } else if (effective_throttle > highcrit) {
        effective_throttle = 1.00;    // 100% full thrust (cavitation region override)
    }
    *(double *)00374 = effective_throttle;
    *(double *)00370 = effective_throttle * 45000.0;
    return effective_throttle;
}

// P66 Rate-of-Descent Lunar Landing Guidance (Don Eyles)
void P66_ROD_GUIDANCE(double dt) {
    double altitude = *(double *)01400;
    double target_descent_rate = -1.0; // m/s
    if (altitude > 100.0) target_descent_rate = -5.0;
    else if (altitude > 30.0) target_descent_rate = -2.5;
    double commanded_accel = 1.62 + (target_descent_rate * 0.15);
    THROTTLE_CONTROL_ROUTINES(commanded_accel);
}

// Lunar Contact Probe Detection (67-inch blue wands)
int EVALUATE_TOUCHDOWN(void) {
    double alt = *(double *)01400;
    if (alt <= 1.7) {
        *(double *)00374 = 0.0; // Engine cutoff command (LUNAR CONTACT LIGHT)
        return 1;
    }
    return 0;
}
